/**
 * @summary List referral earnings with optional date / level / user / ride filters.
 */
export const getAdminListReferralEarningsUrl = (
  params?: AdminListReferralEarningsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/referral-earnings?${stringifiedParams}`
    : `/api/admin/referral-earnings`;
};

