/**
 * @summary List contact form submissions.
 */
export const getAdminListContactSubmissionsUrl = (
  params?: AdminListContactSubmissionsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/site/contact-submissions?${stringifiedParams}`
    : `/api/admin/site/contact-submissions`;
};

